CREATE OR REPLACE FUNCTION public.central_gerir(p_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.central_gestor() OR (public.rc_meu_funcionario_id() IS NOT NULL AND EXISTS(SELECT 1 FROM public.reportes r JOIN public.funcionario_setores fs ON fs.funcao_id=r.setor_destino_id WHERE r.id=p_id AND fs.funcionario_id=public.rc_meu_funcionario_id() AND fs.responsavel)); $$;
CREATE OR REPLACE FUNCTION public.central_ver(p_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.rc_meu_funcionario_id() IS NOT NULL AND EXISTS(SELECT 1 FROM public.reportes r WHERE r.id=p_id AND (public.central_gestor() OR r.reportado_por=public.rc_meu_funcionario_id() OR r.assumido_por=public.rc_meu_funcionario_id() OR EXISTS(SELECT 1 FROM public.funcionario_setores fs WHERE fs.funcionario_id=public.rc_meu_funcionario_id() AND fs.funcao_id IN(r.setor_destino_id,r.setor_origem_id)) OR EXISTS(SELECT 1 FROM public.reporte_envolvidos e WHERE e.reporte_id=r.id AND e.funcionario_id=public.rc_meu_funcionario_id() AND e.ativo))); $$;
CREATE OR REPLACE FUNCTION public.central_abertura_segura() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL THEN IF new.estado<>'pendente' OR new.erro_confirmado OR new.apurado_em IS NOT NULL OR new.apurado_por IS NOT NULL OR cardinality(new.responsaveis_apurados)>0 OR new.corrigido_por IS NOT NULL OR new.validado_por IS NOT NULL OR new.assumido_por IS NOT NULL OR new.conclusao IS NOT NULL OR new.evidencia_apuracao IS NOT NULL OR new.correcao_resultado IS NOT NULL OR new.validacao_evidencia IS NOT NULL OR new.tipo_causa<>'desconhecida' THEN RAISE EXCEPTION 'Uma abertura não define culpa, apuração ou conclusão.'; END IF; IF new.reportado_por IS DISTINCT FROM public.rc_meu_funcionario_id() OR length(trim(new.titulo)) NOT BETWEEN 5 AND 200 OR length(trim(new.descricao)) NOT BETWEEN 15 AND 10000 THEN RAISE EXCEPTION 'Abertura inválida.'; END IF; IF cardinality(new.anexos)>0 THEN RAISE EXCEPTION 'Utiliza o formulário seguro para anexos.'; END IF; END IF; RETURN new; END $$;
CREATE TRIGGER central_abertura_segura BEFORE INSERT ON public.reportes FOR EACH ROW EXECUTE FUNCTION public.central_abertura_segura();
CREATE OR REPLACE FUNCTION public.central_auditar_dados() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE eu uuid:=public.rc_meu_funcionario_id(); antigo jsonb; novo jsonb; BEGIN IF eu IS NULL THEN RETURN new; END IF; antigo:=jsonb_build_object('executor',old.assumido_por,'prazo',old.prazo_resolucao,'data_prevista',old.data_prevista,'confirmado',old.erro_confirmado,'causa',old.tipo_causa,'conclusao',old.conclusao,'evidencia',old.evidencia_apuracao,'responsaveis',old.responsaveis_apurados,'resultado',old.correcao_resultado,'validacao',old.validacao_evidencia); novo:=jsonb_build_object('executor',new.assumido_por,'prazo',new.prazo_resolucao,'data_prevista',new.data_prevista,'confirmado',new.erro_confirmado,'causa',new.tipo_causa,'conclusao',new.conclusao,'evidencia',new.evidencia_apuracao,'responsaveis',new.responsaveis_apurados,'resultado',new.correcao_resultado,'validacao',new.validacao_evidencia); IF antigo IS DISTINCT FROM novo THEN INSERT INTO public.reporte_eventos(reporte_id,autor_id,tipo,texto) VALUES(new.id,eu,CASE WHEN old.conclusao IS DISTINCT FROM new.conclusao OR old.responsaveis_apurados IS DISTINCT FROM new.responsaveis_apurados THEN 'decisao' ELSE 'comentario' END,'Auditoria — anterior: '||antigo::text||' — novo: '||novo::text); END IF; RETURN new; END $$;
CREATE TRIGGER central_auditar_dados AFTER UPDATE ON public.reportes FOR EACH ROW EXECUTE FUNCTION public.central_auditar_dados();
DROP POLICY IF EXISTS qualidade_delete ON storage.objects; CREATE POLICY qualidade_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='qualidade' AND owner=auth.uid() AND NOT public.central_storage_ver(bucket_id,name));
DROP POLICY IF EXISTS qualidade_update ON storage.objects; CREATE POLICY qualidade_update ON storage.objects FOR UPDATE TO authenticated USING(bucket_id='qualidade' AND owner=auth.uid() AND NOT public.central_storage_ver(bucket_id,name)) WITH CHECK(bucket_id='qualidade' AND owner=auth.uid() AND NOT public.central_storage_ver(bucket_id,name));
REVOKE ALL ON FUNCTION public.central_abertura_segura(),public.central_auditar_dados() FROM PUBLIC,anon,authenticated;